1	import Link from "next/link";
2	import { notFound } from "next/navigation";
3	import { Prisma } from "@prisma/client";
4	import { db } from "@/lib/db";
5	import { getAdminUser } from "@/lib/auth";
6	import { recordAdminAction, ADMIN_ACTIONS } from "@/lib/admin-audit";
7	import {
8	  Empty,
9	  StatTile,
10	  TableFrame,
11	  Th,
12	  formatDate,
13	  formatUsd,
14	  truncate,
15	} from "./ui";
16	
17	export const dynamic = "force-dynamic";
18	
19	const PAGE_SIZE = 25;
20	
21	type SortKey = "recent" | "oldest" | "email" | "projects";
22	
23	/**
24	 * Only DATABASE-NATIVE sorts are offered. Balance, lifetime spend and build
25	 * count are all derived from other tables and are computed per PAGE (see
26	 * below) — sorting the page by one of them would silently sort 25 arbitrary
27	 * rows rather than the whole table, which is worse than not offering it.
28	 */
29	const SORTS: Record<SortKey, { label: string; orderBy: Prisma.UserOrderByWithRelationInput }> = {
30	  recent: { label: "Newest", orderBy: { createdAt: "desc" } },
31	  oldest: { label: "Oldest", orderBy: { createdAt: "asc" } },
32	  email: { label: "Email", orderBy: { email: "asc" } },
33	  projects: { label: "Projects", orderBy: { projects: { _count: "desc" } } },
34	};
35	
36	function isSortKey(v: unknown): v is SortKey {
37	  // hasOwnProperty, not `in` — `in` walks the prototype chain, so
38	  // ?sort=constructor passed this guard and reached Prisma as an undefined
39	  // orderBy, producing a reachable 500.
40	  return typeof v === "string" && Object.prototype.hasOwnProperty.call(SORTS, v);
41	}
42	
43	function first(v: string | string[] | undefined): string {
44	  if (Array.isArray(v)) return v[0] ?? "";
45	  return v ?? "";
46	}
47	
48	function href(params: { q: string; sort: SortKey; page: number }): string {
49	  const sp = new URLSearchParams();
50	  if (params.q) sp.set("q", params.q);
51	  if (params.sort !== "recent") sp.set("sort", params.sort);
52	  if (params.page > 1) sp.set("page", String(params.page));
53	  const qs = sp.toString();
54	  return qs ? `/admin/users?${qs}` : "/admin/users";
55	}
56	
57	// ── Per-page rollups ──────────────────────────────────────────────────────
58	// Everything below is keyed by userId and fetched for the CURRENT PAGE ONLY,
59	// in a fixed number of queries (6) regardless of how many users are on it.
60	// No query ever runs inside a loop over users.
61	
62	type BalanceRow = { userId: string; balanceAfter: number };
63	
64	type BuildRollupRow = {
65	  userId: string;
66	  builds: number;
67	  succeeded: number;
68	  failed: number;
69	  costMicros: bigint;
70	  creditsCharged: bigint;
71	  lastBuildAt: Date | null;
72	};
73	
74	type Rollup = {
75	  balance: number;
76	  netDelta: number;
77	  spent: number;
78	  builds: number;
79	  succeeded: number;
80	  failed: number;
81	  costMicros: number;
82	  creditsCharged: number;
83	  lastBuildAt: Date | null;
84	};
85	
86	const EMPTY_ROLLUP: Rollup = {
87	  balance: 0,
88	  netDelta: 0,
89	  spent: 0,
90	  builds: 0,
91	  succeeded: 0,
92	  failed: 0,
93	  costMicros: 0,
94	  creditsCharged: 0,
95	  lastBuildAt: null,
96	};
97	
98	export default async function AdminUsersPage({
99	  searchParams,
100	}: {
101	  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
102	}) {
103	  // Defense in depth — app/admin/layout.tsx is the primary gate, but a layout
104	  // is not an authorization boundary on its own (it does not re-render on
105	  // every navigation within the section). Same idiom as app/admin/page.tsx:
106	  // 404 rather than redirect, so a non-admin learns nothing about this path.
107	  const admin = await getAdminUser();
108	  if (!admin) notFound();
109	
110	  const sp = await searchParams;
111	  const q = first(sp.q).trim();
112	  const sortRaw = first(sp.sort);
113	  const sort: SortKey = isSortKey(sortRaw) ? sortRaw : "recent";
114	  const pageRaw = Number.parseInt(first(sp.page), 10);
115	  const page = Number.isFinite(pageRaw) && pageRaw > 0 ? pageRaw : 1;
116	
117	  // Recorded before the customer data is queried below. `meta` records WHETHER
118	  // a search happened, never the term: on this page the term is almost always a
119	  // customer's email address, and an audit log that quietly accumulates those
120	  // is a second data-protection problem wearing the clothes of a solution —
121	  // the rule is stated at the top of lib/admin-audit.ts.
122	  await recordAdminAction(admin, ADMIN_ACTIONS.userListViewed, {
123	    meta: { page, searched: Boolean(q) },
124	  });
125	
126	  // Search by email, by display name, or by pasting a raw user id straight out
127	  // of a log line or a support ticket.
128	  const where: Prisma.UserWhereInput = q
129	    ? {
130	        OR: [
131	          { email: { contains: q, mode: "insensitive" } },
132	          { name: { contains: q, mode: "insensitive" } },
133	          { id: q },
134	        ],
135	      }
136	    : {};
137	
138	  const [total, users] = await Promise.all([
139	    db.user.count({ where }),
140	    db.user.findMany({
141	      where,
142	      // `id` breaks ties so pagination is stable when timestamps collide.
143	      orderBy: [SORTS[sort].orderBy, { id: "asc" }],
144	      skip: (page - 1) * PAGE_SIZE,
145	      take: PAGE_SIZE,
146	      select: {
147	        id: true,
148	        email: true,
149	        name: true,
150	        role: true,
151	        createdAt: true,
152	        spendCapCredits: true,
153	        _count: { select: { projects: true } },
154	      },
155	    }),
156	  ]);
157	
158	  const ids = users.map((u) => u.id);
159	
160	  // ── Balance for many users, without one query each ────────────────────
161	  // lib/credits.ts `getBalance` reads `balanceAfter` off the user's NEWEST
162	  // ledger row. Postgres does that for a whole set of users in one pass with
163	  // DISTINCT ON: sort by (userId, createdAt DESC, id DESC) and keep the first
164	  // row per userId. `id` is the tiebreak so two rows written inside the same
165	  // millisecond still resolve deterministically to the same row Prisma's
166	  // findFirst would have picked.
167	  const balanceRows = ids.length
168	    ? await db.$queryRaw<BalanceRow[]>`
169	        SELECT DISTINCT ON (l."userId") l."userId", l."balanceAfter"
170	        FROM "CreditLedger" l
171	        WHERE l."userId" IN (${Prisma.join(ids)})
172	        ORDER BY l."userId", l."createdAt" DESC, l."id" DESC`
173	    : [];
174	
175	  // Build has no userId — it hangs off Project — so the per-user build
176	  // rollup is one grouped join rather than a per-user count.
177	  const buildRows = ids.length
178	    ? await db.$queryRaw<BuildRollupRow[]>`
179	        SELECT p."userId",
180	               COUNT(*)::int AS "builds",
181	               COUNT(*) FILTER (WHERE b."status" = 'SUCCEEDED')::int AS "succeeded",
182	               COUNT(*) FILTER (WHERE b."status" = 'FAILED')::int AS "failed",
183	               COALESCE(SUM(b."costMicros"), 0)::bigint AS "costMicros",
184	               COALESCE(SUM(b."creditsCharged"), 0)::bigint AS "creditsCharged",
185	               MAX(b."createdAt") AS "lastBuildAt"
186	        FROM "Build" b
187	        JOIN "Project" p ON p."id" = b."projectId"
188	        WHERE p."userId" IN (${Prisma.join(ids)})
189	        GROUP BY p."userId"`
190	    : [];
191	
192	  const [spentRows, netRows] = ids.length
193	    ? await Promise.all([
194	        db.creditLedger.groupBy({
195	          by: ["userId"],
196	          where: { userId: { in: ids }, delta: { lt: 0 } },
197	          _sum: { delta: true },
198	        }),
199	        // The ledger is append-only and starts at zero, so the sum of every
200	        // delta MUST equal the newest row's balanceAfter. Cheap to check here
201	        // (one grouped query for the page) and the only way to notice a
202	        // ledger that has drifted before a customer does.
203	        db.creditLedger.groupBy({
204	          by: ["userId"],
205	          where: { userId: { in: ids } },
206	          _sum: { delta: true },
207	        }),
208	      ])
209	    : [[], []];
210	
211	  const rollups = new Map<string, Rollup>(ids.map((id) => [id, { ...EMPTY_ROLLUP }]));
212	  for (const r of balanceRows) {
213	    const u = rollups.get(r.userId);
214	    if (u) u.balance = r.balanceAfter;
215	  }
216	  for (const r of buildRows) {
217	    const u = rollups.get(r.userId);
218	    if (!u) continue;
219	    u.builds = Number(r.builds);
220	    u.succeeded = Number(r.succeeded);
221	    u.failed = Number(r.failed);
222	    u.costMicros = Number(r.costMicros);
223	    u.creditsCharged = Number(r.creditsCharged);
224	    u.lastBuildAt = r.lastBuildAt;
225	  }
226	  // `userId` is nullable on CreditLedger — erasure detaches rows rather than
227	  // deleting them (see prisma/schema.prisma). Both queries above filter
228	  // `userId: { in: ids }`, so a null can never actually appear here; the guard
229	  // exists because TypeScript cannot see through a Prisma `where`, and a `!`
230	  // would silently become wrong if either filter ever changed.
231	  for (const r of spentRows) {
232	    const u = r.userId === null ? undefined : rollups.get(r.userId);
233	    // Deltas are negative for spend; show it as a positive number.
234	    if (u) u.spent = Math.abs(r._sum.delta ?? 0);
235	  }
236	  for (const r of netRows) {
237	    const u = r.userId === null ? undefined : rollups.get(r.userId);
238	    if (u) u.netDelta = r._sum.delta ?? 0;
239	  }
240	
241	  const pageCount = Math.max(1, Math.ceil(total / PAGE_SIZE));
242	  const drifted = [...rollups.values()].filter((r) => r.balance !== r.netDelta).length;
243	
244	  return (
245	    <div className="mx-auto max-w-6xl px-6 py-10">
246	      <div className="mb-8">
247	        <Link
248	          href="/admin"
249	          className="text-xs text-black/50 underline-offset-4 hover:underline dark:text-white/50"
250	        >
251	          ← kodely admin
252	        </Link>
253	        <div className="mt-1 text-lg font-semibold tracking-tight">Users</div>
254	        <p className="text-sm text-black/60 dark:text-white/60">
255	          Read-only. Per-customer credits, builds and cost — the view that answers a billing
256	          email.
257	        </p>
258	      </div>
259	
260	      <div className="mb-6 grid grid-cols-2 gap-4 sm:grid-cols-4">
261	        <StatTile label="Users matching" value={total} />
262	        <StatTile label="On this page" value={users.length} />
263	        <StatTile label="Page" value={`${page} / ${pageCount}`} />
264	        <StatTile
265	          label="Ledger drift"
266	          value={drifted}
267	          tone={drifted > 0 ? "warn" : undefined}
268	          hint="balanceAfter vs sum of deltas, this page"
269	        />
270	      </div>
271	
272	      <form method="get" action="/admin/users" className="mb-6 flex flex-wrap items-center gap-2">
273	        <input
274	          type="search"
275	          name="q"
276	          defaultValue={q}
277	          placeholder="Search email, name or user id"
278	          aria-label="Search users"
279	          className="w-full max-w-sm rounded-xl border border-black/10 bg-transparent px-3 py-2 text-sm outline-none placeholder:text-black/40 focus:border-black/30 dark:border-white/10 dark:placeholder:text-white/40 dark:focus:border-white/30"
280	        />
281	        <select
282	          name="sort"
283	          defaultValue={sort}
284	          aria-label="Sort users"
285	          className="rounded-xl border border-black/10 bg-transparent px-3 py-2 text-sm outline-none dark:border-white/10"
286	        >
287	          {(Object.keys(SORTS) as SortKey[]).map((k) => (
288	            <option key={k} value={k}>
289	              {SORTS[k].label}
290	            </option>
291	          ))}
292	        </select>
293	        <button
294	          type="submit"
295	          className="rounded-xl border border-black/10 px-3 py-2 text-sm font-medium hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/5"
296	        >
297	          Search
298	        </button>
299	        {q ? (
300	          <Link
301	            href="/admin/users"
302	            className="text-sm text-black/50 underline-offset-4 hover:underline dark:text-white/50"
303	          >
304	            Clear
305	          </Link>
306	        ) : null}
307	      </form>
308	
309	      {users.length === 0 ? (
310	        <Empty>{q ? `No users match “${truncate(q, 40)}”.` : "No users yet."}</Empty>
311	      ) : (
312	        <TableFrame>
313	          <thead>
314	            <tr className="border-b border-black/10 text-xs text-black/50 dark:border-white/10 dark:text-white/50">
315	              <Th>Email</Th>
316	              <Th>Signed up</Th>
317	              <Th>Role</Th>
318	              <Th align="right">Projects</Th>
319	              <Th align="right">Builds</Th>
320	              <Th align="right">Balance</Th>
321	              <Th align="right">Spent</Th>
322	              <Th align="right">Cost</Th>
323	            </tr>
324	          </thead>
325	          <tbody className="divide-y divide-black/10 dark:divide-white/10">
326	            {users.map((u) => {
327	              const r = rollups.get(u.id) ?? EMPTY_ROLLUP;
328	              const drift = r.balance !== r.netDelta;
329	              return (
330	                <tr key={u.id}>
331	                  <td className="max-w-xs px-4 py-2">
332	                    <Link
333	                      href={`/admin/users/${u.id}`}
334	                      className="font-medium underline-offset-4 hover:underline"
335	                    >
336	                      {truncate(u.email, 44)}
337	                    </Link>
338	                    {u.name ? (
339	                      <div className="text-xs text-black/50 dark:text-white/50">
340	                        {truncate(u.name, 44)}
341	                      </div>
342	                    ) : null}
343	                  </td>
344	                  <td className="whitespace-nowrap px-4 py-2 tabular-nums text-black/70 dark:text-white/70">
345	                    {formatDate(u.createdAt)}
346	                  </td>
347	                  <td className="px-4 py-2 text-black/70 dark:text-white/70">
348	                    {u.role === "ADMIN" ? (
349	                      <span className="font-medium">ADMIN</span>
350	                    ) : (
351	                      <span className="text-black/50 dark:text-white/50">{u.role}</span>
352	                    )}
353	                  </td>
354	                  <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
355	                    {u._count.projects}
356	                  </td>
357	                  <td className="whitespace-nowrap px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
358	                    {r.builds}
359	                    {r.builds > 0 ? (
360	                      <span className="ml-2 text-xs">
361	                        <span className="text-emerald-600 dark:text-emerald-400">{r.succeeded}</span>
362	                        <span className="text-black/30 dark:text-white/30"> / </span>
363	                        <span className="text-red-600 dark:text-red-400">{r.failed}</span>
364	                      </span>
365	                    ) : null}
366	                  </td>
367	                  <td className="whitespace-nowrap px-4 py-2 text-right tabular-nums">
368	                    <span className={r.balance === 0 ? "text-red-600 dark:text-red-400" : ""}>
369	                      {r.balance}
370	                    </span>
371	                    {drift ? (
372	                      <span
373	                        className="ml-1 text-amber-600 dark:text-amber-500"
374	                        title={`Ledger drift: newest balanceAfter is ${r.balance} but deltas sum to ${r.netDelta}`}
375	                      >
376	                        !
377	                      </span>
378	                    ) : null}
379	                    {u.spendCapCredits !== null ? (
380	                      <div className="text-xs text-black/50 dark:text-white/50">
381	                        cap {u.spendCapCredits}
382	                      </div>
383	                    ) : null}
384	                  </td>
385	                  <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
386	                    {r.spent}
387	                  </td>
388	                  <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
389	                    {formatUsd(r.costMicros, 4)}
390	                  </td>
391	                </tr>
392	              );
393	            })}
394	          </tbody>
395	        </TableFrame>
396	      )}
397	
398	      <div className="mt-4 flex items-center justify-between text-sm">
399	        <span className="text-black/50 dark:text-white/50">
400	          {total === 0
401	            ? "0 users"
402	            : `${(page - 1) * PAGE_SIZE + 1}–${Math.min(page * PAGE_SIZE, total)} of ${total}`}
403	        </span>
404	        <span className="flex gap-2">
405	          {page > 1 ? (
406	            <Link
407	              href={href({ q, sort, page: page - 1 })}
408	              className="rounded-xl border border-black/10 px-3 py-1.5 hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/5"
409	            >
410	              Previous
411	            </Link>
412	          ) : null}
413	          {page < pageCount ? (
414	            <Link
415	              href={href({ q, sort, page: page + 1 })}
416	              className="rounded-xl border border-black/10 px-3 py-1.5 hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/5"
417	            >
418	              Next
419	            </Link>
420	          ) : null}
421	        </span>
422	      </div>
423	
424	      <p className="mt-6 text-xs text-black/50 dark:text-white/50">
425	        Balance is the newest ledger row&apos;s balanceAfter, matching lib/credits.ts. Spent is the
426	        sum of negative deltas. Cost is real model spend across every build on the user&apos;s
427	        projects, charged or not — failed builds cost us money and are never billed.
428	      </p>
429	    </div>
430	  );
431	}
