30	// Session tokens are stored hashed, so a database read never yields a usable cookie.
31	function hashToken(token: string) {
32	  return createHash("sha256").update(token).digest("hex");
33	}
34	
35	export async function createSession(userId: string) {
36	  const token = randomBytes(32).toString("base64url");
37	  const expiresAt = new Date(Date.now() + SESSION_DAYS * 86_400_000);
38	  await db.session.create({ data: { userId, tokenHash: hashToken(token), expiresAt } });
39	
40	  const jar = await cookies();
41	  jar.set(SESSION_COOKIE, token, {
42	    httpOnly: true,
43	    sameSite: "lax",
44	    secure: process.env.NODE_ENV === "production",
45	    path: "/",
46	    expires: expiresAt,
47	  });
48	}
