61	  count: number;
62	  /** Share of all classified failures in the window. */
63	  share: number;
64	  /** Count within the recent half of the window. */
65	  recent: number;
66	  /** Share of failures within the recent half. Null when that half had none. */
67	  recentShare: number | null;
68	  lastSeen: Date | null;
69	  /** Most recent raw error in this family — collapsed and truncated before render. */
70	  sample: string;
71	};
72	
73	export type HealthData = {
74	  since: Date;
75	  now: Date;
76	  midpoint: Date;
77	  unit: "hour" | "day";
78	
79	  totalAllTime: number;
80	  total: number;
81	  succeeded: number;
82	  failed: number;
83	  running: number;
84	  stuck: number;
85	
86	  buckets: Bucket[];
87	  peakFailureRate: { rate: number; start: Date } | null;
88	
89	  families: FamilyStat[];
90	  failuresTotal: number;
91	  failuresSampled: number;
92	
93	  timings: Timing[];
94	  repairs: { attempts: number; count: number }[];
95	  repaired: number;
96	  succeededFirstTry: number;
97	
98	  costMicros: number;
99	  sdkStampedBuilds: number;
100	};
