102	function bucketStarts(since: Date, now: Date, unit: "hour" | "day"): Date[] {
103	  const stepMs = unit === "hour" ? 3_600_000 : 86_400_000;
104	  // Align to a UTC boundary so these line up with Postgres date_trunc, which
105	  // truncates the stored (UTC) timestamp.
106	  const first = Math.floor(since.getTime() / stepMs) * stepMs;
107	  const last = Math.floor(now.getTime() / stepMs) * stepMs;
108	  const out: Date[] = [];
109	  for (let t = first; t <= last; t += stepMs) out.push(new Date(t));
110	  return out;
111	}
112	
113	export async function loadHealthData(windowKey: WindowKey): Promise<HealthData> {
114	  const cfg = WINDOWS[windowKey];
115	  const now = new Date();
116	  const since = new Date(now.getTime() - cfg.hours * 3_600_000);
117	  const midpoint = new Date(since.getTime() + (now.getTime() - since.getTime()) / 2);
118	  const stuckBefore = new Date(now.getTime() - STUCK_AFTER_MS);
119	
120	  const inWindow = { createdAt: { gte: since } };
121	
122	  // Two literal statements rather than one with the unit bound in, so the
123	  // truncation unit is never string-interpolated into SQL under any code path.
124	  const bucketRows: BucketRow[] =
125	    cfg.unit === "hour"
126	      ? await db.$queryRaw<BucketRow[]>`
127	          SELECT date_trunc('hour', b."createdAt") AS "bucket",
128	                 COUNT(*)::int AS "total",
129	                 COUNT(*) FILTER (WHERE b."status" = 'SUCCEEDED')::int AS "succeeded",
130	                 COUNT(*) FILTER (WHERE b."status" = 'FAILED')::int AS "failed",
131	                 COUNT(*) FILTER (WHERE b."status" NOT IN ('SUCCEEDED', 'FAILED'))::int AS "running"
132	          FROM "Build" b
133	          WHERE b."createdAt" >= ${since}
134	          GROUP BY 1
135	          ORDER BY 1`
136	      : await db.$queryRaw<BucketRow[]>`
137	          SELECT date_trunc('day', b."createdAt") AS "bucket",
138	                 COUNT(*)::int AS "total",
139	                 COUNT(*) FILTER (WHERE b."status" = 'SUCCEEDED')::int AS "succeeded",
140	                 COUNT(*) FILTER (WHERE b."status" = 'FAILED')::int AS "failed",
141	                 COUNT(*) FILTER (WHERE b."status" NOT IN ('SUCCEEDED', 'FAILED'))::int AS "running"
142	          FROM "Build" b
143	          WHERE b."createdAt" >= ${since}
144	          GROUP BY 1
145	          ORDER BY 1`;
146	
147	  const [
148	    totalAllTime,
149	    statusCounts,
150	    stuck,
151	    failuresTotal,
152	    failureRows,
153	    timingRows,
154	    repairRows,
155	    succeededFirstTry,
156	    costTotals,
157	    sdkStampedBuilds,
158	  ] = await Promise.all([
159	    db.build.count(),
160	    db.build.groupBy({ by: ["status"], where: inWindow, _count: { _all: true } }),
161	    db.build.count({
162	      where: { status: { notIn: ["SUCCEEDED", "FAILED"] }, createdAt: { lt: stuckBefore } },
163	    }),
164	    db.build.count({ where: { ...inWindow, status: "FAILED" } }),
165	    db.build.findMany({
166	      where: { ...inWindow, status: "FAILED" },
167	      select: { error: true, createdAt: true },
168	      orderBy: { createdAt: "desc" },
169	      take: FAILURE_SAMPLE_CAP,
170	    }),
171	    // Duration comes from the two timestamps rather than a stored field, so
172	    // it has to be defended: endedAt is null while a build is in flight, and
173	    // clock skew between the two writes has produced at least one row in this
174	    // database where endedAt is 2ms BEFORE createdAt. A negative duration in
175	    // a percentile is worse than a missing one.
176	    db.$queryRaw<TimingRow[]>`
177	      SELECT b."status",
178	             COUNT(*)::int AS "n",
179	             percentile_cont(0.5) WITHIN GROUP (
180	               ORDER BY (EXTRACT(EPOCH FROM (b."endedAt" - b."createdAt")) * 1000)::float8
181	             ) AS "p50",
182	             percentile_cont(0.95) WITHIN GROUP (
183	               ORDER BY (EXTRACT(EPOCH FROM (b."endedAt" - b."createdAt")) * 1000)::float8
184	             ) AS "p95",
185	             MAX((EXTRACT(EPOCH FROM (b."endedAt" - b."createdAt")) * 1000)::float8) AS "max"
186	      FROM "Build" b
187	      WHERE b."createdAt" >= ${since}
188	        AND b."endedAt" IS NOT NULL
189	        AND b."endedAt" >= b."createdAt"
190	      GROUP BY b."status"
191	      ORDER BY b."status"`,
192	    db.build.groupBy({
193	      by: ["repairAttempts"],
194	      where: inWindow,
195	      _count: { _all: true },
196	      orderBy: { repairAttempts: "asc" },
197	    }),
198	    db.build.count({ where: { ...inWindow, status: "SUCCEEDED", repairAttempts: 0 } }),
199	    db.build.aggregate({ where: inWindow, _sum: { costMicros: true } }),
200	    // The only rows that PROVE they came from the subscription engine. See the
201	    // caveat rendered on the page: this is a floor, not the true count.
202	    db.build.count({ where: { ...inWindow, model: "claude-agent-sdk-subscription" } }),
203	  ]);
204	
205	  const succeeded = statusCounts.find((s) => s.status === "SUCCEEDED")?._count._all ?? 0;
206	  const failed = statusCounts.find((s) => s.status === "FAILED")?._count._all ?? 0;
207	  const total = statusCounts.reduce((acc, s) => acc + s._count._all, 0);
208	  const running = total - succeeded - failed;
209	
210	  // Fill the gaps so the x-axis is real time, not "hours that happened to have
211	  // a build". A quiet stretch is information.
212	  const byBucket = new Map(bucketRows.map((r) => [r.bucket.getTime(), r]));
213	  const buckets: Bucket[] = bucketStarts(since, now, cfg.unit).map((start) => {
214	    const r = byBucket.get(start.getTime());
215	    return {
216	      start,
217	      total: r ? Number(r.total) : 0,
218	      succeeded: r ? Number(r.succeeded) : 0,
219	      failed: r ? Number(r.failed) : 0,
220	      running: r ? Number(r.running) : 0,
221	    };
222	  });
223	
224	  let peakFailureRate: { rate: number; start: Date } | null = null;
225	  for (const b of buckets) {
226	    const finished = b.succeeded + b.failed;
227	    if (finished === 0) continue;
228	    const rate = (b.failed / finished) * 100;
229	    if (!peakFailureRate || rate > peakFailureRate.rate) {
230	      peakFailureRate = { rate, start: b.start };
231	    }
232	  }
233	
234	  // ── Clustering ────────────────────────────────────────────────────────
235	  const counts = new Map<FamilyId, FamilyStat>();
236	  for (const f of FAMILIES) {
237	    counts.set(f.id, {
238	      id: f.id,
239	      count: 0,
240	      share: 0,
241	      recent: 0,
242	      recentShare: null,
243	      lastSeen: null,
244	      sample: "",
245	    });
246	  }
247	  let recentTotal = 0;
248	  for (const row of failureRows) {
249	    const id = classifyError(row.error);
250	    const stat = counts.get(id);
251	    if (!stat) continue;
252	    stat.count += 1;
253	    // failureRows is ordered newest-first, so the first row a family sees is
254	    // its most recent one.
255	    if (!stat.lastSeen) {
256	      stat.lastSeen = row.createdAt;
257	      stat.sample = row.error ?? "(no error text recorded)";
258	    }
259	    if (row.createdAt >= midpoint) {
260	      stat.recent += 1;
261	      recentTotal += 1;
262	    }
263	  }
264	
265	  const sampled = failureRows.length;
266	  const families = [...counts.values()]
267	    .filter((f) => f.count > 0)
268	    .map((f) => ({
269	      ...f,
270	      share: sampled === 0 ? 0 : (f.count / sampled) * 100,
271	      recentShare: recentTotal === 0 ? null : (f.recent / recentTotal) * 100,
272	    }))
273	    .sort((a, b) => b.count - a.count || a.id.localeCompare(b.id));
274	
275	  return {
276	    since,
277	    now,
278	    midpoint,
279	    unit: cfg.unit,
280	    totalAllTime,
281	    total,
282	    succeeded,
283	    failed,
284	    running,
285	    stuck,
286	    buckets,
287	    peakFailureRate,
288	    families,
289	    failuresTotal,
290	    failuresSampled: sampled,
291	    timings: timingRows.map((t) => ({
292	      status: t.status,
293	      n: Number(t.n),
294	      p50: t.p50 === null ? null : Number(t.p50),
295	      p95: t.p95 === null ? null : Number(t.p95),
296	      max: t.max === null ? null : Number(t.max),
297	    })),
298	    repairs: repairRows.map((r) => ({ attempts: r.repairAttempts, count: r._count._all })),
299	    repaired: repairRows.reduce((acc, r) => acc + (r.repairAttempts > 0 ? r._count._all : 0), 0),
300	    succeededFirstTry,
301	    costMicros: costTotals._sum.costMicros ?? 0,
302	    sdkStampedBuilds,
303	  };
304	}
305	
306	// Re-exported so page.tsx can narrow a caught Prisma error without importing
307	// the client itself.
308	export function isPrismaError(e: unknown): boolean {
