import Link from "next/link";
import { notFound } from "next/navigation";
import { getAdminUser } from "@/lib/auth";
import { ADMIN_ACTIONS, recordAdminAction } from "@/lib/admin-audit";
import { family } from "../health/errors";
import {
  DEFAULT_FILTERS,
  LOW_DATA_BUILDS,
  MODEL_NONE,
  PAGE_SIZE,
  REPAIR_FILTERS,
  REPAIR_KEYS,
  STATUS_FILTERS,
  STATUS_KEYS,
  buildsHref,
  isFamilyId,
  isRepairKey,
  isStatusKey,
  loadBuildList,
  type BuildFilters,
} from "./data";
import {
  Dash,
  Empty,
  FamilyBadge,
  Notice,
  RatingMark,
  StatTile,
  TableFrame,
  Th,
  formatDateTime,
  formatDuration,
  formatUsd,
  modelLabel,
  oneLine,
  statusClass,
  truncate,
} from "./ui";

export const dynamic = "force-dynamic";

function first(v: string | string[] | undefined): string {
  if (Array.isArray(v)) return v[0] ?? "";
  return v ?? "";
}

const selectClass =
  "rounded-xl border border-black/10 bg-transparent px-3 py-2 text-sm outline-none dark:border-white/10";

export default async function AdminBuildsPage({
  searchParams,
}: {
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
}) {
  // Defense in depth — app/admin/layout.tsx is the primary gate, but a layout
  // is not an authorization boundary on its own: it does not re-render on every
  // navigation within the section. 404 rather than redirect, so a non-admin
  // learns nothing about this path.
  const admin = await getAdminUser();
  if (!admin) notFound();

  const sp = await searchParams;
  const statusRaw = first(sp.status);
  const repairRaw = first(sp.repair);
  const familyRaw = first(sp.family);
  const pageRaw = Number.parseInt(first(sp.page), 10);

  // Every guard below is hasOwnProperty, never `in`. `in` walks the prototype
  // chain, so `?status=constructor` would pass a check whose entire job is to
  // say the value is one of ours, and reach Prisma as an undefined where clause
  // — a reachable 500 that has already happened three times in this codebase.
  const filters: BuildFilters = {
    ...DEFAULT_FILTERS,
    status: isStatusKey(statusRaw) ? statusRaw : "all",
    repair: isRepairKey(repairRaw) ? repairRaw : "all",
    family: isFamilyId(familyRaw) ? familyRaw : null,
    model: first(sp.model).trim(),
    projectId: first(sp.project).trim(),
    q: first(sp.q).trim(),
    page: Number.isFinite(pageRaw) && pageRaw > 0 ? pageRaw : 1,
  };

  // Awaited BEFORE any customer data is read, so there is no window in which an
  // admin has the prompts and the log does not have the row.
  //
  // `dashboard.viewed` is the closest name lib/admin-audit.ts owns: it is
  // defined as "Cost, margin, and 50 recent builds including customer prompts",
  // which is this surface with a different pagination. It is NOT the right
  // name — `build_list.viewed` is — but that vocabulary is closed, this file
  // may not edit it, and inventing a name by string literal would defeat the
  // point of a closed set. `view` in meta keeps the two readable apart in the
  // log until the real names land; see the report accompanying this change.
  //
  // meta records WHETHER a search happened, never the term. On this page the
  // term is a substring of a customer's prompt — an audit log that quietly
  // accumulates customer content is a second data-protection problem wearing
  // the clothes of a solution. The rule is stated at the top of
  // lib/admin-audit.ts.
  await recordAdminAction(admin, ADMIN_ACTIONS.dashboardViewed, {
    meta: {
      view: "build_list",
      page: filters.page,
      searched: Boolean(filters.q),
      status: filters.status,
      repair: filters.repair,
      family: filters.family ?? "any",
      scopedToProject: Boolean(filters.projectId),
    },
  });

  const list = await loadBuildList(filters);

  // The family filter implies FAILED — a family only exists for a failure — so
  // the status control has to show what is actually in force.
  const shownStatus = filters.family ? "failed" : filters.status;
  const familyOffered = shownStatus === "all" || shownStatus === "failed";

  const succeeded = list.rows.filter((r) => r.status === "SUCCEEDED").length;
  const failed = list.rows.filter((r) => r.status === "FAILED").length;
  const repaired = list.rows.filter((r) => r.repairAttempts > 0).length;
  const dominant = list.families[0] ?? null;
  const filtered =
    shownStatus !== "all" ||
    filters.repair !== "all" ||
    Boolean(filters.model) ||
    Boolean(filters.family) ||
    Boolean(filters.projectId) ||
    Boolean(filters.q);

  const from = list.total === 0 ? 0 : (list.page - 1) * PAGE_SIZE + 1;
  const to = Math.min(list.page * PAGE_SIZE, list.total);

  return (
    <div className="mx-auto max-w-6xl px-6 py-10">
      <div className="mb-8">
        <Link
          href="/admin"
          className="text-xs text-black/50 underline-offset-4 hover:underline dark:text-white/50"
        >
          ← kodely admin
        </Link>
        <div className="mt-1 text-lg font-semibold tracking-tight">Builds</div>
        <p className="text-sm text-black/60 dark:text-white/60">
          Read-only. Every generation this system has run — the view that answers &ldquo;why did
          this one go wrong&rdquo;. Prompts are truncated here; the full text is on a build&apos;s
          own page.
        </p>
      </div>

      {list.totalAllTime < LOW_DATA_BUILDS ? (
        <div className="mb-6">
          <Notice>
            <span className="font-medium">Low data.</span> This database holds{" "}
            <span className="tabular-nums">{list.totalAllTime}</span> build
            {list.totalAllTime === 1 ? "" : "s"} in total
            {dominant ? (
              <>
                , and <span className="tabular-nums">{dominant.count}</span> of{" "}
                <span className="tabular-nums">{list.classified}</span> classified failure
                {list.classified === 1 ? "" : "s"} land in{" "}
                <span className="font-medium">{family(dominant.id).label}</span> — blame:{" "}
                {family(dominant.id).blame}
              </>
            ) : null}
            . Treat every share, rate and comparison on these pages as an anecdote about specific
            rows, not a measurement. A run of identical config failures is one incident, not a
            trend.
          </Notice>
        </div>
      ) : null}

      <div className="mb-6 grid grid-cols-2 gap-4 sm:grid-cols-4">
        <StatTile
          label="Builds matching"
          value={list.total}
          hint={
            list.totalIsFloor
              ? `at least — scan capped at ${list.classified}`
              : filtered
                ? `${list.totalAllTime} in total`
                : "no filters"
          }
        />
        <StatTile
          label="On this page"
          value={
            <>
              <span className="text-emerald-600 dark:text-emerald-400">{succeeded}</span>
              <span className="text-black/30 dark:text-white/30"> / </span>
              <span className="text-red-600 dark:text-red-400">{failed}</span>
            </>
          }
          hint={`${list.rows.length} row${list.rows.length === 1 ? "" : "s"} · succeeded / failed`}
        />
        <StatTile
          label="Needed a repair"
          value={repaired}
          tone={repaired > 0 ? "warn" : undefined}
          hint="on this page"
        />
        <StatTile label="Page" value={`${list.page} / ${list.pageCount}`} />
      </div>

      <form method="get" action="/admin/builds" className="mb-6 flex flex-wrap items-center gap-2">
        <input
          type="search"
          name="q"
          defaultValue={filters.q}
          placeholder="Search prompt text"
          aria-label="Search build prompts"
          className="w-full max-w-xs rounded-xl border border-black/10 bg-transparent px-3 py-2 text-sm outline-none placeholder:text-black/40 focus:border-black/30 dark:border-white/10 dark:placeholder:text-white/40 dark:focus:border-white/30"
        />
        <select name="status" defaultValue={shownStatus} aria-label="Filter by status" className={selectClass}>
          {STATUS_KEYS.map((k) => (
            <option key={k} value={k}>
              {STATUS_FILTERS[k].label}
            </option>
          ))}
        </select>
        <select name="model" defaultValue={filters.model} aria-label="Filter by model" className={selectClass}>
          <option value="">Any model</option>
          {list.models.map((m) => (
            <option key={m || MODEL_NONE} value={m || MODEL_NONE}>
              {modelLabel(m)}
            </option>
          ))}
        </select>
        <select
          name="family"
          defaultValue={filters.family ?? ""}
          aria-label="Filter by error family"
          disabled={!familyOffered}
          className={`${selectClass} disabled:opacity-40`}
        >
          <option value="">Any error family</option>
          {list.families.map((f) => (
            <option key={f.id} value={f.id}>
              {family(f.id).label} ({f.count})
            </option>
          ))}
        </select>
        <select name="repair" defaultValue={filters.repair} aria-label="Filter by repair" className={selectClass}>
          {REPAIR_KEYS.map((k) => (
            <option key={k} value={k}>
              {REPAIR_FILTERS[k].label}
            </option>
          ))}
        </select>
        {filters.projectId ? <input type="hidden" name="project" value={filters.projectId} /> : null}
        <button
          type="submit"
          className="rounded-xl border border-black/10 px-3 py-2 text-sm font-medium hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/5"
        >
          Apply
        </button>
        {filtered ? (
          <Link
            href="/admin/builds"
            className="text-sm text-black/50 underline-offset-4 hover:underline dark:text-white/50"
          >
            Clear
          </Link>
        ) : null}
      </form>

      {filters.projectId ? (
        <p className="mb-4 text-xs text-black/50 dark:text-white/50">
          Scoped to project <span className="font-mono">{truncate(filters.projectId, 30)}</span>.{" "}
          <Link href={buildsHref({ ...filters, projectId: "", page: 1 })} className="underline underline-offset-2">
            Show every project
          </Link>
        </p>
      ) : null}

      {filters.family ? (
        <p className="mb-4 text-xs text-black/50 dark:text-white/50">
          Filtering by error family classifies {list.classified} failure
          {list.classified === 1 ? "" : "s"} in TypeScript (the rules in app/admin/health/errors.ts
          are regexes, not SQL), so status is pinned to Failed
          {list.totalIsFloor
            ? ` and the count is a floor — the scan stopped at ${list.classified} rows.`
            : "."}
        </p>
      ) : null}

      {list.rows.length === 0 ? (
        <Empty>
          {filtered
            ? "No builds match these filters."
            : "No builds yet. Nothing has been generated on this instance."}
        </Empty>
      ) : (
        <TableFrame>
          <thead>
            <tr className="border-b border-black/10 text-xs text-black/50 dark:border-white/10 dark:text-white/50">
              <Th>Started</Th>
              <Th>Status</Th>
              <Th>Project</Th>
              <Th>Owner</Th>
              <Th>Model</Th>
              <Th align="right">Took</Th>
              <Th align="right">Rep</Th>
              <Th align="right">Tokens</Th>
              <Th align="right">Cost</Th>
              <Th align="right">Cr</Th>
              <Th>Rated</Th>
              <Th>Prompt / error</Th>
            </tr>
          </thead>
          <tbody className="divide-y divide-black/10 dark:divide-white/10">
            {list.rows.map((b) => (
              <tr key={b.id}>
                <td className="whitespace-nowrap px-4 py-2 tabular-nums">
                  <Link
                    href={`/admin/builds/${b.id}`}
                    className="underline-offset-4 hover:underline"
                  >
                    {formatDateTime(b.createdAt)}
                  </Link>
                </td>
                <td className={`px-4 py-2 font-medium ${statusClass(b.status)}`}>{b.status}</td>
                <td className="max-w-[9rem] px-4 py-2 text-black/70 dark:text-white/70">
                  <Link
                    href={`/admin/sites/${b.project.id}`}
                    className="underline-offset-4 hover:underline"
                  >
                    {truncate(b.project.name, 22)}
                  </Link>
                </td>
                <td className="max-w-[11rem] px-4 py-2 text-black/70 dark:text-white/70">
                  <Link
                    href={`/admin/users/${b.project.user.id}`}
                    className="underline-offset-4 hover:underline"
                  >
                    {truncate(b.project.user.email, 26)}
                  </Link>
                </td>
                <td className="whitespace-nowrap px-4 py-2 text-black/70 dark:text-white/70">
                  {b.model ? (
                    truncate(b.model, 26)
                  ) : (
                    <span className="text-black/30 dark:text-white/30">not stamped</span>
                  )}
                </td>
                <td className="whitespace-nowrap px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
                  {formatDuration(b.createdAt, b.endedAt)}
                </td>
                <td
                  className={`px-4 py-2 text-right tabular-nums ${
                    b.repairAttempts > 0
                      ? "font-medium text-amber-600 dark:text-amber-500"
                      : "text-black/70 dark:text-white/70"
                  }`}
                >
                  {b.repairAttempts}
                </td>
                <td className="whitespace-nowrap px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
                  {b.inputTokens + b.outputTokens === 0 ? (
                    <Dash />
                  ) : (
                    <span title={`${b.inputTokens} in / ${b.outputTokens} out`}>
                      {b.inputTokens + b.outputTokens}
                    </span>
                  )}
                </td>
                <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
                  {formatUsd(b.costMicros, 4)}
                </td>
                <td
                  className={`px-4 py-2 text-right tabular-nums ${
                    b.status !== "SUCCEEDED" && b.creditsCharged > 0
                      ? "font-medium text-amber-600 dark:text-amber-500"
                      : "text-black/70 dark:text-white/70"
                  }`}
                >
                  {b.creditsCharged}
                </td>
                <td className="whitespace-nowrap px-4 py-2 text-xs">
                  {b.ratings.length === 0 ? <Dash /> : <RatingMark rating={b.ratings[0].rating} />}
                </td>
                <td className="max-w-sm px-4 py-2 text-black/60 dark:text-white/60">
                  {oneLine(b.prompt, 70)}
                  {b.familyId ? (
                    <div className="mt-1">
                      <FamilyBadge id={b.familyId} showBlame={false} />
                    </div>
                  ) : null}
                </td>
              </tr>
            ))}
          </tbody>
        </TableFrame>
      )}

      <div className="mt-4 flex items-center justify-between text-sm">
        <span className="text-black/50 dark:text-white/50">
          {list.total === 0
            ? "0 builds"
            : `${from}–${to} of ${list.totalIsFloor ? `at least ${list.total}` : list.total}`}
        </span>
        <span className="flex gap-2">
          {list.page > 1 ? (
            <Link
              href={buildsHref({ ...filters, status: shownStatus, page: list.page - 1 })}
              className="rounded-xl border border-black/10 px-3 py-1.5 hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/5"
            >
              Previous
            </Link>
          ) : null}
          {list.page < list.pageCount ? (
            <Link
              href={buildsHref({ ...filters, status: shownStatus, page: list.page + 1 })}
              className="rounded-xl border border-black/10 px-3 py-1.5 hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/5"
            >
              Next
            </Link>
          ) : null}
        </span>
      </div>

      <p className="mt-6 text-xs text-black/50 dark:text-white/50">
        Error families come from app/admin/health/errors.ts — the same classifier /admin/health
        clusters by, imported rather than re-implemented. Cost is real model spend; credits are what
        the customer was charged, and a failed build charged anything but zero is a fault (shown in
        amber). This page never renders the contents of a build&apos;s file snapshot.
      </p>
    </div>
  );
}

input.old_string:
  reply: Reply | null;
  /** True when a reply exists but a later build on this project may own it. */
  replyIsAmbiguous: boolean;
  counterpart: BuildDetail | null;
  counterpartSource: ComparisonSource | null;
  /** Whether the project has ANY successful build other than this one. */
  hasSuccessElsewhere: boolean;
  siblingCount: number;
};

input.new_string:
  reply: Reply | null;
  /**
   * True when a reply landed in the window but this build did not succeed. The
   * generate route only writes an assistant message after a SUCCESS, so such a
   * row belongs to something else — most likely the seeded welcome message from
   * lib/seed-project.ts. Flagged rather than hidden, and never presented as
   * this build's output.
   */
  replyIsSuspect: boolean;
  counterpart: BuildDetail | null;
  counterpartSource: ComparisonSource | null;
  /** Whether the project has ANY successful build other than this one. */
  hasSuccessElsewhere: boolean;
  siblingCount: number;
  /** The project's other builds, newest first, for the comparison picker. */
  siblings: Sibling[];
};

export type Sibling = {
  id: string;
  createdAt: Date;
  status: string;
  repairAttempts: number;
};

  db.build.count({ where: { projectId } }),
  db.build.findMany({
    where: { projectId, id: { not: id } },
    orderBy: [{ createdAt: "desc" }, { id: "desc" }],
    take: SIBLING_LIMIT,
    select: { id: true, createdAt: true, status: true, repairAttempts: true },
  }),
]);

input.old_string:
  ratings: ratingsMap.get(id) ?? [],
  reply,
  // The seeded welcome message (lib/seed-project.ts) is also an assistant
  // row, so a first build can pick up a reply that predates any generation
  // only if it landed inside the window — flagged rather than hidden.
  replyIsAmbiguous: reply !== null && nextBuild === null && build.status !== "SUCCEEDED",
  counterpart: counterpartRaw ? toDetail(counterpartRaw) : null,
  counterpartSource,
  hasSuccessElsewhere: lastSuccess !== null,
  siblingCount,
};

input.new_string:
/** Snapshot paths listed on the detail page before it stops and says how many are left. */
export const SNAPSHOT_PATH_LIMIT = 400;

/** Other builds on the same project offered as comparison targets. */
export const SIBLING_LIMIT = 50;

input.content:
import Link from "next/link";
import { notFound } from "next/navigation";
import { getAdminUser } from "@/lib/auth";
import { ADMIN_ACTIONS, recordAdminAction } from "@/lib/admin-audit";
import { BLAME_LABEL, family } from "../../health/errors";
import {
  SNAPSHOT_PATH_LIMIT,
  diffSnapshots,
  loadBuildDetail,
  type BuildDetail,
  type ComparisonSource,
} from "../data";
import {
  Dash,
  Fact,
  FamilyBadge,
  Notice,
  Panel,
  PanelEmpty,
  RatingMark,
  StatTile,
  TableFrame,
  Th,
  formatBytes,
  formatDateTime,
  formatDuration,
  formatInt,
  formatUsd,
  modelLabel,
  statusClass,
  truncate,
} from "../ui";

export const dynamic = "force-dynamic";

function first(v: string | string[] | undefined): string {
  if (Array.isArray(v)) return v[0] ?? "";
  return v ?? "";
}

const COMPARISON_LABEL: Record<ComparisonSource, string> = {
  last_success: "the project's most recent successful build",
  previous_build: "the previous build on this project",
  explicit: "the build you picked",
};

function totalTokens(b: BuildDetail): number {
  return b.inputTokens + b.outputTokens + b.cacheReadTokens + b.cacheWriteTokens;
}

/** One comparison row. Renders both sides and marks the pair when they differ. */
function Row({
  label,
  a,
  b,
  differs,
}: {
  label: string;
  a: React.ReactNode;
  b: React.ReactNode;
  differs: boolean;
}) {
  return (
    <tr className={differs ? "bg-black/[0.03] dark:bg-white/[0.04]" : undefined}>
      <td className="px-4 py-2 text-xs text-black/50 dark:text-white/50">{label}</td>
      <td className="px-4 py-2 tabular-nums">{a}</td>
      <td className="px-4 py-2 tabular-nums">{b}</td>
    </tr>
  );
}

export default async function AdminBuildDetailPage({
  params,
  searchParams,
}: {
  params: Promise<{ id: string }>;
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
}) {
  // Defense in depth — see app/admin/page.tsx. The layout gate is the primary
  // one, but a layout must not be the sole authorization boundary.
  const admin = await getAdminUser();
  if (!admin) notFound();

  const { id } = await params;
  const vsId = first((await searchParams).vs).trim();

  // Awaited BEFORE the lookup, so probing an id that does not exist still
  // leaves a trace, and so there is no window in which an admin has the prompt
  // and the log does not have the row.
  //
  // `dashboard.viewed` is the closest name the closed vocabulary in
  // lib/admin-audit.ts offers — it is defined as the builds-and-prompts
  // surface. The right name is `build.viewed`, which does not exist there and
  // which this change may not add; see the accompanying report. `buildId` in
  // meta is an id, not content, and is what makes the row answer "who opened
  // this build". No targetType is set: ADMIN_TARGET_TYPES has no `build`, and
  // filing a build under `project` would silently pollute the "everything done
  // to this site" filter that /admin/sites/[id] reads off targetType+targetId.
  //
  // Nothing derived from the prompt goes in meta — the rule at the top of
  // lib/admin-audit.ts.
  await recordAdminAction(admin, ADMIN_ACTIONS.dashboardViewed, {
    meta: { view: "build_detail", buildId: id, compared: Boolean(vsId) },
  });

  const data = await loadBuildDetail(id, vsId);
  if (!data) notFound();

  const { build, counterpart, counterpartSource } = data;
  const fam = build.familyId ? family(build.familyId) : null;

  const chargedFailure = build.status !== "SUCCEEDED" && build.creditsCharged > 0;
  const ledgerAgainstFailure = build.status !== "SUCCEEDED" && data.ledger.some((l) => l.delta < 0);
  const snapshotShown = build.snapshot.entries.slice(0, SNAPSHOT_PATH_LIMIT);
  const diff = counterpart ? diffSnapshots(counterpart.snapshot, build.snapshot) : null;

  return (
    <div className="mx-auto max-w-6xl px-6 py-10">
      <div className="mb-8">
        <Link
          href="/admin/builds"
          className="text-xs text-black/50 underline-offset-4 hover:underline dark:text-white/50"
        >
          ← Builds
        </Link>
        <div className="mt-1 flex flex-wrap items-baseline gap-3">
          <span className={`text-lg font-semibold tracking-tight ${statusClass(build.status)}`}>
            {build.status}
          </span>
          <span className="text-lg font-semibold tracking-tight">
            {formatDateTime(build.createdAt)}
          </span>
        </div>
        <p className="text-sm text-black/60 dark:text-white/60">
          <Link href={`/admin/sites/${build.project.id}`} className="underline underline-offset-2">
            {truncate(build.project.name, 50)}
          </Link>{" "}
          · owned by{" "}
          <Link
            href={`/admin/users/${build.project.user.id}`}
            className="underline underline-offset-2"
          >
            {build.project.user.email}
          </Link>{" "}
          ·{" "}
          <Link
            href={`/admin/builds?project=${build.project.id}`}
            className="underline underline-offset-2"
          >
            {data.siblingCount} build{data.siblingCount === 1 ? "" : "s"} on this project
          </Link>
        </p>
        <p className="mt-1 font-mono text-xs text-black/40 dark:text-white/40">{build.id}</p>
      </div>

      <div className="mb-8 grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-6">
        <StatTile
          label="Duration"
          value={formatDuration(build.createdAt, build.endedAt)}
          hint={build.endedAt ? `ended ${formatDateTime(build.endedAt)}` : "never ended"}
        />
        <StatTile label="Model" value={<span className="text-sm">{modelLabel(build.model)}</span>} />
        <StatTile
          label="Tokens"
          value={formatInt(totalTokens(build))}
          hint={`${formatInt(build.inputTokens)} in · ${formatInt(build.outputTokens)} out`}
        />
        <StatTile label="Real cost" value={formatUsd(build.costMicros, 4)} />
        <StatTile
          label="Credits charged"
          value={build.creditsCharged}
          tone={chargedFailure ? "warn" : undefined}
          hint={build.status === "SUCCEEDED" ? undefined : "failed builds are never billed"}
        />
        <StatTile
          label="Repair attempts"
          value={build.repairAttempts}
          tone={build.repairAttempts > 0 ? "warn" : undefined}
          hint={build.repairAttempts === 0 ? "compiled first try" : "did not compile first try"}
        />
      </div>

      {chargedFailure || ledgerAgainstFailure ? (
        <div className="mb-8">
          <Notice tone="warn">
            <span className="font-medium text-amber-700 dark:text-amber-500">Needs a look.</span>{" "}
            {chargedFailure
              ? `This build is ${build.status} but carries creditsCharged=${build.creditsCharged}. `
              : ""}
            {ledgerAgainstFailure
              ? "A negative ledger row points at this build even though it did not succeed. "
              : ""}
            The anti-bill-shock contract in lib/credits.ts says a build that did not succeed is
            recorded at true cost and charged zero.
          </Notice>
        </div>
      ) : null}

      <div className="mb-8 grid gap-6 lg:grid-cols-2">
        <Panel
          title="Prompt"
          subtitle="What the customer asked for, in full. This is the only place in the panel that shows it whole."
        >
          <pre className="max-h-96 overflow-auto rounded-lg border border-black/10 p-3 text-xs leading-relaxed whitespace-pre-wrap dark:border-white/10">
            {build.prompt}
          </pre>
          <p className="mt-2 text-xs text-black/50 dark:text-white/50">
            {formatInt(build.prompt.length)} characters.
          </p>
        </Panel>

        <Panel
          title="Failure"
          subtitle={
            build.status === "FAILED"
              ? "Build.error verbatim, plus the family app/admin/health/errors.ts files it under."
              : "Nothing failed on this build."
          }
        >
          {build.status !== "FAILED" ? (
            <PanelEmpty>
              {build.status === "SUCCEEDED"
                ? "Succeeded — no error recorded."
                : `Status is ${build.status}; no error recorded yet.`}
            </PanelEmpty>
          ) : (
            <>
              <div className="flex flex-wrap items-baseline gap-2">
                {build.familyId ? <FamilyBadge id={build.familyId} /> : null}
                {fam ? (
                  <span className="text-xs text-black/50 dark:text-white/50">
                    blame: {BLAME_LABEL[fam.blame]}
                  </span>
                ) : null}
              </div>
              {fam ? (
                <p className="mt-3 text-xs leading-relaxed text-black/60 dark:text-white/60">
                  {fam.hint}
                </p>
              ) : null}
              <pre className="mt-3 max-h-72 overflow-auto rounded-lg border border-red-500/25 p-3 text-xs leading-relaxed whitespace-pre-wrap text-red-700 dark:text-red-400">
                {build.error && build.error.trim() ? build.error : "(no error text recorded)"}
              </pre>
              {build.familyId ? (
                <p className="mt-2 text-xs text-black/50 dark:text-white/50">
                  <Link
                    href={`/admin/builds?family=${build.familyId}`}
                    className="underline underline-offset-2"
                  >
                    Every build in this family
                  </Link>
                </p>
              ) : null}
            </>
          )}
        </Panel>
      </div>

      <div className="mb-8 grid gap-6 lg:grid-cols-2">
        <Panel
          title="Assistant reply"
          subtitle="Message has no buildId — this is the first assistant message on the project inside this build's window, so it is a correlation, not a foreign key."
        >
          {!data.reply ? (
            <PanelEmpty>
              No assistant message stored for this build. app/api/generate/route.ts only writes one
              after a successful run that produced a reply.
            </PanelEmpty>
          ) : (
            <>
              {data.replyIsSuspect ? (
                <p className="mb-2 text-xs text-amber-600 dark:text-amber-500">
                  This build did not succeed, so this message is almost certainly not its output —
                  most likely the seeded welcome message from lib/seed-project.ts. Shown for
                  completeness, not attributed.
                </p>
              ) : null}
              <pre className="max-h-72 overflow-auto rounded-lg border border-black/10 p-3 text-xs leading-relaxed whitespace-pre-wrap dark:border-white/10">
                {data.reply.content}
              </pre>
              <p className="mt-2 text-xs text-black/50 dark:text-white/50">
                Written {formatDateTime(data.reply.createdAt)}.
              </p>
            </>
          )}
        </Panel>

        <Panel
          title="What the customer thought"
          subtitle="build.rated events from lib/events.ts, matched on props.buildId."
        >
          {data.ratings.length === 0 ? (
            <PanelEmpty>
              No rating. Rating is optional and this instance has recorded none at all yet, so an
              empty panel here says nothing about the build.
            </PanelEmpty>
          ) : (
            <ul className="space-y-2">
              {data.ratings.map((r) => (
                <li key={`${r.createdAt.toISOString()}-${r.rating}`} className="text-sm">
                  <RatingMark rating={r.rating} />
                  {r.reason ? (
                    <span className="ml-2 text-black/60 dark:text-white/60">{truncate(r.reason, 40)}</span>
                  ) : null}
                  <span className="ml-2 text-xs text-black/40 dark:text-white/40 tabular-nums">
                    {formatDateTime(r.createdAt)}
                  </span>
                </li>
              ))}
            </ul>
          )}
        </Panel>
      </div>

      <div className="mb-8">
        <Panel
          title="Comparison"
          subtitle={
            counterpart && counterpartSource
              ? `This build against ${COMPARISON_LABEL[counterpartSource]}. Differing rows are shaded.`
              : "Nothing on this project to compare against."
          }
          footnote={
            counterpart
              ? "Snapshot comparison is by path and byte count only — file contents are never read or rendered here."
              : undefined
          }
        >
          {!counterpart ? (
            <PanelEmpty>
              This is the only build on the project, so there is nothing to put beside it.
            </PanelEmpty>
          ) : (
            <>
              {!data.hasSuccessElsewhere && counterpartSource !== "explicit" ? (
                <p className="mb-3 text-xs text-amber-600 dark:text-amber-500">
                  This project has never had a successful build, so the strong comparison — a
                  failure against the last green run — is not available. Falling back to the
                  previous build, which is a weaker signal.
                </p>
              ) : null}

              <TableFrame>
                <thead>
                  <tr className="border-b border-black/10 text-xs text-black/50 dark:border-white/10 dark:text-white/50">
                    <Th>&nbsp;</Th>
                    <Th>This build</Th>
                    <Th>
                      <Link
                        href={`/admin/builds/${counterpart.id}`}
                        className="underline underline-offset-2"
                      >
                        {counterpart.status === "SUCCEEDED" ? "Last success" : "Counterpart"}
                      </Link>
                    </Th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-black/10 dark:divide-white/10">
                  <Row
                    label="Status"
                    differs={build.status !== counterpart.status}
                    a={<span className={statusClass(build.status)}>{build.status}</span>}
                    b={<span className={statusClass(counterpart.status)}>{counterpart.status}</span>}
                  />
                  <Row
                    label="Started"
                    differs
                    a={formatDateTime(build.createdAt)}
                    b={formatDateTime(counterpart.createdAt)}
                  />
                  <Row
                    label="Took"
                    differs={false}
                    a={formatDuration(build.createdAt, build.endedAt)}
                    b={formatDuration(counterpart.createdAt, counterpart.endedAt)}
                  />
                  <Row
                    label="Model"
                    differs={build.model !== counterpart.model}
                    a={modelLabel(build.model)}
                    b={modelLabel(counterpart.model)}
                  />
                  <Row
                    label="Error family"
                    differs={build.familyId !== counterpart.familyId}
                    a={build.familyId ? <FamilyBadge id={build.familyId} showBlame={false} /> : <Dash />}
                    b={
                      counterpart.familyId ? (
                        <FamilyBadge id={counterpart.familyId} showBlame={false} />
                      ) : (
                        <Dash />
                      )
                    }
                  />
                  <Row
                    label="Repair attempts"
                    differs={build.repairAttempts !== counterpart.repairAttempts}
                    a={build.repairAttempts}
                    b={counterpart.repairAttempts}
                  />
                  <Row
                    label="Prompt length"
                    differs={build.prompt !== counterpart.prompt}
                    a={`${formatInt(build.prompt.length)} chars`}
                    b={`${formatInt(counterpart.prompt.length)} chars`}
                  />
                  <Row
                    label="Input tokens"
                    differs={build.inputTokens !== counterpart.inputTokens}
                    a={formatInt(build.inputTokens)}
                    b={formatInt(counterpart.inputTokens)}
                  />
                  <Row
                    label="Output tokens"
                    differs={build.outputTokens !== counterpart.outputTokens}
                    a={formatInt(build.outputTokens)}
                    b={formatInt(counterpart.outputTokens)}
                  />
                  <Row
                    label="Cache read / write"
                    differs={
                      build.cacheReadTokens !== counterpart.cacheReadTokens ||
                      build.cacheWriteTokens !== counterpart.cacheWriteTokens
                    }
                    a={`${formatInt(build.cacheReadTokens)} / ${formatInt(build.cacheWriteTokens)}`}
                    b={`${formatInt(counterpart.cacheReadTokens)} / ${formatInt(counterpart.cacheWriteTokens)}`}
                  />
                  <Row
                    label="Real cost"
                    differs={build.costMicros !== counterpart.costMicros}
                    a={formatUsd(build.costMicros, 4)}
                    b={formatUsd(counterpart.costMicros, 4)}
                  />
                  <Row
                    label="Credits charged"
                    differs={build.creditsCharged !== counterpart.creditsCharged}
                    a={build.creditsCharged}
                    b={counterpart.creditsCharged}
                  />
                  <Row
                    label="Files written"
                    differs={build.filesWritten !== counterpart.filesWritten}
                    a={build.filesWritten}
                    b={counterpart.filesWritten}
                  />
                  <Row
                    label="Snapshot files"
                    differs={build.snapshot.entries.length !== counterpart.snapshot.entries.length}
                    a={
                      build.snapshot.present ? (
                        `${build.snapshot.entries.length} · ${formatBytes(build.snapshot.totalBytes)}`
                      ) : (
                        <Dash />
                      )
                    }
                    b={
                      counterpart.snapshot.present ? (
                        `${counterpart.snapshot.entries.length} · ${formatBytes(counterpart.snapshot.totalBytes)}`
                      ) : (
