export type SnapshotEntry = { path: string; bytes: number };

export type Snapshot = {
  present: boolean;
  /** Sorted by path. CONTENT IS NEVER CARRIED OUT OF THIS FUNCTION. */
  entries: SnapshotEntry[];
  totalBytes: number;
  /** Set when filesSnapshot is present but is not the {path: content} object it should be. */
  malformed: boolean;
};

/**
 * `Build.filesSnapshot` is the customer's complete generated source, stored as
 * {path: content}. This is the ONLY thing in the section allowed to touch it,
 * and it reduces it to paths and byte counts on the way out.
 *
 * There is no operational reason to read a customer's source from an admin
 * panel: "which files did this build write, and how big were they" answers the
 * debugging question, and rendering the bodies would make this page a source
 * viewer for other people's work. The type is the enforcement — SnapshotEntry
 * has nowhere to put a body.
 */
export function readSnapshot(raw: Prisma.JsonValue | null | undefined): Snapshot {
  if (raw === null || raw === undefined) {
    return { present: false, entries: [], totalBytes: 0, malformed: false };
  }
  if (typeof raw !== "object" || Array.isArray(raw)) {
    return { present: true, entries: [], totalBytes: 0, malformed: true };
  }

  const entries: SnapshotEntry[] = [];
  let totalBytes = 0;
  for (const [path, content] of Object.entries(raw)) {
    // Non-string values shouldn't happen, but the column is Json and a
    // mis-shaped row must not crash the page that exists to diagnose bad rows.
    const bytes =
      typeof content === "string"
        ? Buffer.byteLength(content, "utf8")
        : Buffer.byteLength(JSON.stringify(content ?? null), "utf8");
    entries.push({ path, bytes });
    totalBytes += bytes;
  }
  entries.sort((a, b) => a.path.localeCompare(b.path));
  return { present: true, entries, totalBytes, malformed: false };
}

export type SnapshotDiff = {
  added: SnapshotEntry[];
  removed: SnapshotEntry[];
  changed: { path: string; fromBytes: number; toBytes: number }[];
  unchanged: number;
};

/** Path-and-size diff between two snapshots. Compares sizes; never compares — or reads — content. */
export function diffSnapshots(from: Snapshot, to: Snapshot): SnapshotDiff {
  const fromMap = new Map(from.entries.map((e) => [e.path, e.bytes]));
  const toMap = new Map(to.entries.map((e) => [e.path, e.bytes]));

  const added: SnapshotEntry[] = [];
  const changed: SnapshotDiff["changed"] = [];
  let unchanged = 0;
  for (const [path, bytes] of toMap) {
    const before = fromMap.get(path);
    if (before === undefined) added.push({ path, bytes });
    else if (before !== bytes) changed.push({ path, fromBytes: before, toBytes: bytes });
    else unchanged += 1;
  }
  const removed = from.entries.filter((e) => !toMap.has(e.path));

  return { added, removed, changed, unchanged };
}

