import fs from "node:fs";
import path from "node:path";

const ROOT = "C:/Users/edmem/kodely-prod";
for (const line of fs.readFileSync(path.join(ROOT, ".env"), "utf8").split(/\r?\n/)) {
  const m = line.match(/^\s*([A-Z_0-9]+)\s*=\s*(.*?)\s*$/);
  if (!m) continue;
  let v = m[2];
  if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) v = v.slice(1, -1);
  process.env[m[1]] ??= v;
}
process.env.NODE_ENV ??= "test";

const { registerTsResolution, quietNodeWarnings } = await import(`file:///${ROOT}/scripts/eval/loader.mjs`);
quietNodeWarnings();
registerTsResolution();

const data = await import(`file:///${ROOT}/app/admin/builds/data.ts`);
const { db } = await import(`file:///${ROOT}/lib/db.ts`);

const byProject = new Map();
for (const b of await db.build.findMany({ select: { id: true, projectId: true, status: true }, orderBy: { createdAt: "desc" } })) {
  const l = byProject.get(b.projectId) ?? [];
  l.push(b);
  byProject.set(b.projectId, l);
}
const multi = [...byProject.entries()].filter(([, l]) => l.length > 1);
console.log("projects with >1 build:", multi.map(([p, l]) => `${p}=${l.length}`).join(", "));

const [pid, builds] = multi[0];
const [a, b] = builds;
console.log(`\nsame-project explicit: ${a.id} vs ${b.id} (project ${pid})`);
let d = await data.loadBuildDetail(a.id, b.id);
console.log(`  source=${d.counterpartSource} counterpart=${d.counterpart?.id} ok=${d.counterpart?.id === b.id}`);

// A build id from a DIFFERENT project must be refused.
const foreign = [...byProject.entries()].find(([p]) => p !== pid)[1][0];
d = await data.loadBuildDetail(a.id, foreign.id);
console.log(`\ncross-project explicit refused: vs=${foreign.id} -> source=${d.counterpartSource} counterpart=${d.counterpart?.id ?? "none"} refused=${d.counterpart?.id !== foreign.id}`);

// vs = itself, vs = junk
d = await data.loadBuildDetail(a.id, a.id);
console.log(`self vs self -> source=${d.counterpartSource}`);
d = await data.loadBuildDetail(a.id, "'; drop table \"Build\"; --");
console.log(`junk vs -> source=${d.counterpartSource} counterpart=${d.counterpart?.id ?? "none"}`);
d = await data.loadBuildDetail(a.id, "__proto__");
console.log(`proto vs -> source=${d.counterpartSource}`);

// Prompt search with SQL-ish and wildcard input.
for (const q of ["'; DROP TABLE \"Build\"; --", "%", "_", "bike%"]) {
  const r = await data.loadBuildList({ ...data.DEFAULT_FILTERS, q });
  console.log(`q=${JSON.stringify(q)} -> total=${r.total}`);
}

// siblings list excludes self
d = await data.loadBuildDetail(a.id, "");
console.log(`\nsiblings for ${a.id}: count=${d.siblingCount} list=${d.siblings.length} includesSelf=${d.siblings.some((s) => s.id === a.id)}`);

process.exit(0);

